package com.bank.session;

// Expensive-to-compute per-session risk profile. IMPORTANT: it must NOT hold
// a strong reference back to its Session key, or the entry would self-pin.
class RiskProfile {
    private final int riskScore;
    private final String accountId; // store the id (a copy), NOT the Session

    RiskProfile(int riskScore, String accountId) {
        this.riskScore = riskScore;
        this.accountId = accountId;
    }

    int getRiskScore() { return riskScore; }
    String getAccountId() { return accountId; }
}
