package com.bank.session;

import java.util.Collections;
import java.util.Map;
import java.util.WeakHashMap;

// Entries live exactly as long as the Session key is referenced elsewhere.
// Wrapped in synchronizedMap because WeakHashMap is NOT thread-safe.
class RiskProfileCache {
    private final Map<Session, RiskProfile> cache =
            Collections.synchronizedMap(new WeakHashMap<>());

    void put(Session session, RiskProfile profile) {
        cache.put(session, profile);
    }

    RiskProfile get(Session session) {
        return cache.get(session);
    }

    // Touching the map triggers lazy purge of dead entries.
    int size() {
        return cache.size();
    }
}
