package com.bank.session;

import java.util.Map;
import java.util.WeakHashMap;
import java.util.logging.*;

public class WeakHashMapDemo {
    private static final Logger log = Logger.getLogger(WeakHashMapDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws InterruptedException {
        // CORRECT: key by the Session OBJECT identity.
        RiskProfileCache cache = new RiskProfileCache();
        Session session = new Session("SESS-1", "SAV2001");
        cache.put(session, new RiskProfile(720, "SAV2001"));
        log.info(() -> "CORRECT cache size with live session: " + cache.size());

        session = null; // session manager discards the session
        for (int i = 0; i < 5 && cache.size() > 0; i++) { System.gc(); Thread.sleep(200); }
        log.info(() -> "CORRECT cache size after session dropped: " + cache.size()
                + " (entry auto-removed — lifetime followed the key)");

        // PITFALL: key by an INTERNED String — never collected, never removed.
        Map<String, RiskProfile> brokenCache = new WeakHashMap<>();
        String internedKey = "SESS-INTERNED".intern(); // strongly held by the pool
        brokenCache.put(internedKey, new RiskProfile(650, "CUR3001"));
        String localRef = internedKey;
        internedKey = null;
        localRef = localRef; // still reachable from pool regardless
        log.info(() -> "BROKEN cache size with interned key: " + brokenCache.size());
        for (int i = 0; i < 5; i++) { System.gc(); Thread.sleep(100); }
        log.warning(() -> "BROKEN cache size after GC: " + brokenCache.size()
                + " (NEVER shrinks — interned String is strongly reachable from the pool)");

        log.warning(() -> "Lesson: WeakHashMap keys must be identity objects you control, "
                + "never interned Strings or cached boxed values; and it is NOT thread-safe.");
    }
}

